#!/usr/bin/env bash
set -euo pipefail
NETWATCH_CONTROL_HUB_PATCH=1
SOURCE_VERSION=0.5.5
TARGET_VERSION=0.5.6
TARGET="${NETWATCH_INSTALLED_DIR:-${1:-$HOME/.local/share/netwatch-system-updater}}"
TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT
base64 -d <<'PAYLOAD' | gzip -d > "$TMP"

PAYLOAD
chmod 700 "$TMP"
NETWATCH_INSTALLED_DIR="$TARGET" /bin/bash "$TMP"
